var boom=UnityEngine.Object.FindObjectsByType<IndianOceanAssets.ShooterSurvival.ExtraHelpBuffScript>(UnityEngine.FindObjectsSortMode.None).Where(h=>h.helpType==HelpType.Boombardino).ToArray();
var pool=UnityEngine.Object.FindFirstObjectByType<IndianOceanAssets.ShooterSurvival.BulletPooler>();
var scripts=UnityEngine.Object.FindObjectsByType<IndianOceanAssets.ShooterSurvival.BulletScript>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None);
return new{helpers=boom.Select(h=>new{h.name,weapons=h.GetComponentsInChildren<IndianOceanAssets.ShooterSurvival.WeaponScript>(true).Select(w=>new{w.name,kind=w.bulletKind.ToString(),w.TotalProjectilesSpawned}).ToArray()}).ToArray(),bulletScripts=scripts.Where(s=>s.transform.root.name.Contains("Boom")||s.transform.root.name.Contains("Bomb")).Take(8).Select(s=>new{name=s.name,root=s.transform.root.name,s.gameObject.activeSelf,s.gameObject.activeInHierarchy,parent=s.transform.parent?.name,rootActive=s.transform.root.gameObject.activeSelf}).ToArray(),pool=pool.name};
